create table if not exists "migrations" ("id" bigint generated by default as identity primary key, "name" varchar(255) not null unique, "module" varchar(255) not null, "batch" integer not null);
create table if not exists "table_owners" ("table_name" varchar(255) primary key, "module" varchar(255) not null);
create table if not exists "secret_columns" ("table_name" varchar(255) not null, "column_name" varchar(255) not null, constraint "secret_columns_pkey" primary key ("table_name", "column_name"));
create table if not exists "schema_markers" ("table_name" varchar(255) not null, "column_name" varchar(255) default '' not null, "marker" varchar(32) not null, "value" varchar(255), constraint "schema_markers_pkey" primary key ("table_name", "column_name", "marker"));
create table "accounts" ("id" bigint generated by default as identity primary key, "email" varchar(255) not null, "password" varchar(255) not null, "api_secret" varchar(255), "created_at" timestamptz(3) default now() not null, "updated_at" timestamptz(3) default now() not null);
create unique index "accounts_email_unique" on "accounts" ("email");
